#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    vector<long long> d(n + 1, 0);
    d[1] = 26;
    long long w = 0;
    // w is the sum of the last k-1 values of d (a sliding window).
    for (int i = 2; i <= n; i++) {
        w = (w + d[i - 1]) % MOD;
        if (i - k >= 1) w = (w - d[i - k] + MOD) % MOD;
        d[i] = (25 * w + (i < k ? 26 : 0)) % MOD;
    }
    printf("%lld\n", d[n]);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        final long MOD = 1000000007L;
        int n = nextInt(), k = nextInt();
        long[] d = new long[n + 1];
        d[1] = 26;
        long w = 0;
        // w is the sum of the last k-1 values of d (a sliding window).
        for (int i = 2; i <= n; i++) {
            w = (w + d[i - 1]) % MOD;
            if (i - k >= 1) w = (w - d[i - k] + MOD) % MOD;
            d[i] = (25 * w + (i < k ? 26 : 0)) % MOD;
        }
        System.out.println(d[n]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const MOD = 1000000007
	n, k := int(nextInt()), int(nextInt())
	d := make([]int64, n+1)
	d[1] = 26
	var w int64
	// w is the sum of the last k-1 values of d (a sliding window).
	for i := 2; i <= n; i++ {
		w = (w + d[i-1]) % MOD
		if i-k >= 1 {
			w = (w - d[i-k] + MOD) % MOD
		}
		d[i] = 25 * w % MOD
		if i < k {
			d[i] = (d[i] + 26) % MOD
		}
	}
	fmt.Println(d[n])
}
